mapper.select:


    and r.content_id = #{contentId}
    and r.account_id = #{accountId}
    and r.publish_mode = #{publishMode}
    and r.status = #{status}

        and r.planned_time >= cast(#{params.beginTime} as date)


        and r.planned_time < cast(#{params.endTime} as date) + interval '1 day'


order by r.planned_time desc, r.record_id desc

select count(*) from abr_publish_record
where content_id = #{contentId}

    and status = #{status}
    and status in ('scheduled', 'published')
